/* Family rewards use earned, browser-local coins; no real-money purchases. */
(function(root){
'use strict';
function request(balance,reward,requests,id){if(!reward||!Number.isInteger(reward.cost)||reward.cost<0||!Number.isFinite(balance)||balance<reward.cost||requests.some(r=>r.rewardId===reward.id&&r.status==='pending'))return null;return {balance:balance-reward.cost,requests:[...requests,{id,rewardId:reward.id,name:reward.name,cost:reward.cost,status:'pending'}]};}
function decide(balance,requests,id,approve){let changed=false;const next=requests.map(r=>{if(r.id!==id||r.status!=='pending')return r;changed=true;if(!approve)balance+=r.cost;return {...r,status:approve?'approved':'declined'};});return changed?{balance,requests:next}:null;}
const core={request,decide};if(typeof module!=='undefined'&&module.exports)module.exports=core;if(!root.document)return;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=()=>state.familyRewards||(state.familyRewards={items:[],requests:[]});
const saveAll=()=>save();
function parentCard(){const f=get();return `<section class="card card-pad"><div class="eyebrow">LITTLE THINGS TO ENJOY TOGETHER</div><h2>Family rewards</h2><p>Parent-managed reward catalog and pending child requests. Add/Edit opens an editor; Save applies changes. Approval or decline is applied immediately. Separate from optional meal-routine participation coins.</p><p>Create rewards together. These saved rewards are separate from fictional check-in demo data. Coins are reserved when requested and returned if you choose “Not now.”</p>${f.items.length?f.items.map(r=>`<div class="routine-row"><strong>${esc(r.name)}</strong> · ${r.cost} coins${r.note?`<p>${esc(r.note)}</p>`:''}<div class="routine-actions"><button class="secondary" data-reward="edit" data-id="${esc(r.id)}">Edit</button><button class="secondary" data-reward="remove" data-id="${esc(r.id)}">Remove</button></div></div>`).join(''):'<p>No family rewards yet. Add one like “Choose dinner tonight.”</p>'}<div class="routine-actions"><button class="primary" data-reward="add">Add reward</button></div><h3>Waiting for parent</h3>${f.requests.filter(r=>r.status==='pending').map(r=>`<div class="routine-row"><strong>${esc(r.name)}</strong> · ${r.cost} coins<div class="routine-actions"><button class="primary" data-reward="approve" data-id="${esc(r.id)}">Approve</button><button class="secondary" data-reward="decline" data-id="${esc(r.id)}">Not now</button></div></div>`).join('')||'<p>No requests waiting.</p>'}<p class="routine-note">Family rewards and requests stay in this browser; no messages are sent to another device.</p></section>`;}
function mountShop(){const old=document.querySelector('#family-reward-shop');if(old)old.remove();if(page!=='wardrobe')return;const f=get(),el=document.createElement('section');el.id='family-reward-shop';el.className='card card-pad';el.style.margin='0 0 20px';el.innerHTML=`<div class="eyebrow">A LITTLE SOMETHING TOGETHER</div><h2>Family rewards</h2><p>Ask a parent to approve a reward. Coins are held while you wait.</p>${f.items.length?f.items.map(r=>{const pending=f.requests.some(x=>x.rewardId===r.id&&x.status==='pending');return `<div class="routine-row"><strong>${esc(r.name)}</strong> · ${r.cost} coins${r.note?`<p>${esc(r.note)}</p>`:''}<div class="routine-actions"><button class="secondary" data-reward="request" data-id="${esc(r.id)}" ${pending?'disabled':''}>${pending?'Waiting for parent':'Ask for reward'}</button></div></div>`}).join(''):'<p>A parent can add family rewards in the parent portal.</p>'}${f.requests.filter(r=>r.status!=='pending').slice(-3).map(r=>`<p class="routine-note">${esc(r.name)}: ${r.status==='approved'?'Approved!':'Not now; your coins were returned.'}</p>`).join('')}`;content.prepend(el);}
function rewardForm(reward){const r=reward||{name:'',cost:50,note:''};showModal(`<div class="eyebrow">FAMILY REWARD</div><h2>${reward?'Edit reward':'Add a family reward'}</h2><form id="family-reward-form" class="routine-form"><label>Reward name<input name="name" maxlength="50" required value="${esc(r.name)}" placeholder="Choose dinner tonight"></label><label>Coin cost<input name="cost" type="number" min="0" max="99999" step="1" required value="${r.cost}"></label><label>Optional note<input name="note" maxlength="120" value="${esc(r.note||'')}"></label><p class="routine-error" id="reward-error" role="alert"></p><div class="routine-actions"><button type="button" class="secondary" id="reward-cancel">Cancel</button><button class="primary">Save reward</button></div></form>`);document.querySelector('#reward-cancel').onclick=()=>modal.close();document.querySelector('#family-reward-form').onsubmit=e=>{e.preventDefault();if(!root.parentPortalUnlocked?.())return;const data=new FormData(e.target),name=data.get('name').trim(),cost=Number(data.get('cost')),note=data.get('note').trim();if(!name||!Number.isInteger(cost)||cost<0||cost>99999){document.querySelector('#reward-error').textContent='Enter a name and a whole-number coin cost.';return;}const f=get(),item={id:reward?.id||crypto.randomUUID(),name,cost,note};if(reward)f.items=f.items.map(x=>x.id===reward.id?item:x);else f.items.push(item);saveAll();modal.close();root.refreshParentPortal();toast('Family reward saved.');};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-reward]');if(!b)return;const action=b.dataset.reward,f=get(),parent=root.parentPortalUnlocked?.()&&!!b.closest('#routine-parent');if(action==='request'){if(!b.closest('#family-reward-shop')||document.querySelector('#portal-select').value!=='child')return;const r=f.items.find(x=>x.id===b.dataset.id),next=request(state.coins,r,f.requests,crypto.randomUUID());if(!next){toast('This reward is waiting for a parent or needs more coins. There is no rush.');return;}state.coins=next.balance;f.requests=next.requests;saveAll();mountShop();toast('Your request is waiting for a parent.');return;}if(!parent)return;if(action==='add')rewardForm();else if(action==='edit'){const r=f.items.find(x=>x.id===b.dataset.id);if(r)rewardForm(r);}else if(action==='remove'){const r=f.items.find(x=>x.id===b.dataset.id);if(r&&confirm('Remove this reward? Existing requests will still be available.')){f.items=f.items.filter(x=>x.id!==r.id);saveAll();root.refreshParentPortal();}}else if(action==='approve'||action==='decline'){const result=decide(state.coins,f.requests,b.dataset.id,action==='approve');if(!result)return;state.coins=result.balance;f.requests=result.requests;saveAll();root.refreshParentPortal();toast(action==='approve'?'Reward approved.':'Not now. The coins were returned.');}});
root.FamilyRewards={parentCard,mountShop};
})(typeof window==='undefined'?globalThis:window);
